import { execFileSync } from "node:child_process";
import { cargoCommand } from "../managed-cargo.mjs";
import {
  readFileSync,
  writeFileSync,
  mkdirSync,
  readdirSync,
  unlinkSync,
} from "node:fs";

const argumentHelp = JSON.parse(
  readFileSync(
    new URL("../../docs/maintenance/arguments.json", import.meta.url),
    "utf8",
  ),
);
const cell = (value) =>
  String(value ?? "")
    .replaceAll("|", "\\|")
    .replaceAll("\n", " ");
export function renderCommand(root) {
  const lines = [
    "<!-- Generated by pnpm docs:generate. Edit command definitions or shared docs/cli help. -->",
    "",
    `# ${root.path}`,
    "",
    "This reference describes the application command parser. See [capabilities](../reference/capabilities.md) for profile and qualification limits.",
    "",
  ];
  function visit(c, depth) {
    if (depth) lines.push(`## ${c.path}`, "");
    if (c.about)
      lines.push(
        c.about
          .replace(/^#+ /gm, "### ")
          .replaceAll("(server-config.md)", "(../reference/configuration.md)")
          .replaceAll("(workflows.md)", "(jj-workflow.md)")
          .replaceAll("(../browser.md)", "(../guides/browsing.md)")
          .replaceAll("(../capture-preview.md)", "(../guides/capture.md)"),
        "",
      );
    lines.push("```text", c.usage, "```", "");
    if (c.aliases.length)
      lines.push(
        `Aliases: ${c.aliases.map((v) => "`" + v + "`").join(", ")}.`,
        "",
      );
    if (c.arguments.length) {
      lines.push(
        "| Argument or option | Meaning | Default / values |",
        "| --- | --- | --- |",
      );
      for (const arg of c.arguments) {
        const names = [
          arg.short && "-" + arg.short,
          arg.long && "--" + arg.long,
          ...(arg.short_aliases ?? []).map((alias) => "-" + alias),
          ...(arg.aliases ?? []).map((alias) => "--" + alias),
        ].filter(Boolean);
        const label = names.length
          ? names.join(", ") +
            (arg.values?.length ? " <" + arg.values.join(" ") + ">" : "")
          : arg.id;
        const help = arg.help || argumentHelp[arg.id];
        if (!help) throw Error(`Undocumented argument: ${c.path} ${arg.id}`);
        const details = [
          help,
          arg.required && "Required.",
          arg.global && "Inherited by subcommands.",
        ]
          .filter(Boolean)
          .join(" ");
        const values = [
          arg.defaults?.length && "Default: " + arg.defaults.join(", "),
          arg.possible?.length && "Values: " + arg.possible.join(", "),
        ]
          .filter(Boolean)
          .join("; ");
        lines.push(
          `| \`${cell(label)}\` | ${cell(details)} | ${cell(values)} |`,
        );
      }
      lines.push("");
    }
    for (const sub of c.commands) visit(sub, depth + 1);
  }
  visit(root, 0);
  return lines.join("\n") + "\n";
}
export function expectedReferences() {
  const data = JSON.parse(
    execFileSync(
      ...(process.env.JJ_STORE_DOC_REFERENCE ? [process.env.JJ_STORE_DOC_REFERENCE, []] : cargoCommand([
        "run",
        "--quiet",
        "--locked",
        "-p",
        "jj-store",
        "--example",
        "docs_reference",
      ])),
      { encoding: "utf8", maxBuffer: 16 * 1024 * 1024 },
    ),
  );
  const files = new Map();
  for (const c of [...data.client, data.server])
    files.set(
      `docs/site/cli/${c.path === "jj store" ? "jj-store-client" : c.path.replaceAll(" ", "-")}.md`,
      renderCommand(c),
    );
  files.set(
    "docs/site/reference/defaults.md",
    "# Configuration defaults\n\nGenerated from the production Rust defaults. See [configuration](configuration.md) for units, valid contexts and override behavior.\n\n```json\n" +
      JSON.stringify(data.configuration_defaults, null, 2) +
      "\n```\n",
  );
  const api = JSON.parse(readFileSync("schemas/openapi.json", "utf8"));
  const groups = {
    installation: ["Installation and device", []],
    code: ["Code browsing and mutations", []],
    collaboration: ["Agents, reviews and discussions", []],
    work: ["Projects and tasks", []],
    workflows: ["Workflows and execution history", []],
    search: ["Search and indexing", []],
    administration: ["Repository administration and replication", []],
  };
  for (const [path, methods] of Object.entries(api.paths)) {
    const group =
      !path.startsWith("/v1/repos/") || path.includes("/local/")
        ? "installation"
        : /\/(agent|reviews|threads|reactions|emojis|collab)(\/|$)/.test(path)
          ? "collaboration"
          : /\/(workflows|workflow-events)(\/|$)/.test(path)
            ? "workflows"
            : /\/(projects|tasks|work)(\/|$)/.test(path)
              ? "work"
              : /\/(search|index)(\/|$)/.test(path)
                ? "search"
                : /\/(snapshot|log|commits|files|trees|operations|bookmarks|workspaces|mutations|conflicts|evolution|compare|diff)(\/|$)/.test(
                      path,
                    )
                  ? "code"
                  : "administration";
    for (const [verb, op] of Object.entries(methods)) {
      if (!["get", "head", "post", "put", "delete", "patch"].includes(verb))
        continue;
      groups[group][1].push(
        `## ${verb.toUpperCase()} ${path}`,
        "",
        op.description || op.summary || "",
        "",
        "```text",
        JSON.stringify(op, null, 2),
        "```",
        "",
      );
    }
  }
  const index = [
    "# HTTP API reference",
    "",
    "Generated from the application OpenAPI contract. Read [transport semantics](transport.md) before integrating. Route presence does not imply availability for every repository profile; consult [capabilities](capabilities.md).",
    "",
    "Each operation retains its exact parameters, bodies, response variants and schema references. Resolve `#/components/schemas/NAME` in the [data types](api/types.md) reference.",
    "",
  ];
  for (const [key, [title, body]] of Object.entries(groups)) {
    index.push(`- [${title}](api/${key}.md)`);
    files.set(
      `docs/site/reference/api/${key}.md`,
      [
        `# ${title}`,
        "",
        "Generated from OpenAPI. See [transport semantics](../transport.md), [capabilities](../capabilities.md) and [data types](types.md).",
        "",
        ...body,
      ].join("\n") + "\n",
    );
  }
  index.push("- [Data types](api/types.md)", "");
  files.set("docs/site/reference/http-api.md", index.join("\n"));
  const types = [
    "# API data types",
    "",
    "Generated from the application OpenAPI schemas. Exact identity widths, required fields and variants are preserved. Do not coerce large JSON integers into JavaScript numbers. See [transport semantics](../transport.md).",
    "",
  ];
  for (const [name, schema] of Object.entries(api.components?.schemas ?? {}))
    types.push(
      `## ${name}`,
      "",
      "```text",
      JSON.stringify(schema, null, 2),
      "```",
      "",
    );
  files.set("docs/site/reference/api/types.md", types.join("\n") + "\n");
  return files;
}
export function compareReferences(expected, write = false) {
  for (const [path, text] of expected) {
    if (write) {
      mkdirSync(path.slice(0, path.lastIndexOf("/")), { recursive: true });
      writeFileSync(path, text);
    } else if (readFileSync(path, "utf8") !== text)
      throw Error(`Stale reference: ${path}; run pnpm docs:generate`);
  }
}
export function references(write = false) {
  const expected = expectedReferences();
  for (const name of readdirSync("docs/site/cli")) {
    const path = `docs/site/cli/${name}`;
    if (name !== "index.md" && name.endsWith(".md") && !expected.has(path)) {
      if (write) unlinkSync(path);
      else throw Error(`Obsolete generated reference: ${path}`);
    }
  }
  compareReferences(expected, write);
}
